(()=>{'use strict';if(window.__radarPrototypeVersionV222)return;window.__radarPrototypeVersionV222=true;function add(){if(document.getElementById('radar-version-v222'))return true;const posts=[...document.querySelectorAll('button')].find(x=>/postos/i.test(x.textContent||''));if(!posts)return false;const b=document.createElement('div');b.id='radar-version-v222';b.textContent='V 222';Object.assign(b.style,{position:'fixed',zIndex:'99999',background:'rgba(8,18,28,.9)',color:'#fff',font:'700 14px Arial',padding:'5px 12px',borderRadius:'14px',boxShadow:'0 2px 8px #0008',pointerEvents:'none'});document.body.appendChild(b);const place=()=>{const r=posts.getBoundingClientRect();b.style.left=Math.round(r.left+r.width/2-b.offsetWidth/2)+'px';b.style.top=Math.round(r.bottom+8)+'px'};place();addEventListener('resize',place);return true}let n=0,t=setInterval(()=>{if(add()||++n>200)clearInterval(t)},100);})();